<?php require_once __DIR__.'/includes/auth.php';$page_title='Uploaded Files';$rows=db()->query('SELECT * FROM uploads ORDER BY created_at DESC')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-title"><div><h1>Uploaded Files</h1><p>Receipt metadata stored by the API.</p></div></div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>FILE</th><th>USER ID</th><th>MIME</th><th>SIZE</th><th>DATE</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['stored_name'])?></td><td><?=$r['user_id']?></td><td><?=e($r['mime'])?></td><td><?=number_format($r['size']/1024,1)?> KB</td><td><?=e(date('d M Y',strtotime($r['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div></section><?php include __DIR__.'/includes/footer.php';?>
